import toolUtil from '@/utils/toolUtil'

const menu = {
    list() {
        // 获取原始的菜单数据字符串
        let menus = toolUtil.storageGet("menus");
        if (!menus) {
            return null;
        }
        
        // 1. 将字符串解析为对象
        let menuList = eval('(' + menus + ')');
        
        // 2. 找到“管理员”角色并注入新菜单
        if (menuList && menuList.length > 0) {
            menuList.forEach(roleItem => {
                // 检查角色名，确保是管理员或admin
                if ((roleItem.roleName === '管理员' || roleItem.roleName === 'admin') && roleItem.backMenu) {
                    
                    // 检查是否已经注入过，防止重复显示
                    const hasPeijian = roleItem.backMenu.some(m => m.menu === '配件管理');
                    
                    if (!hasPeijian) {
                        // 往管理员的菜单列表里 push 一个新对象
                        roleItem.backMenu.push({
                            "child": [
                                {
                                    "appFrontIcon": "cuIcon-goods",
                                    "buttons": ["新增","查看","修改","删除"], // 注意：这里通常不能有空格
                                    "menu": "配件信息列表",
                                    "menuJump": "列表",
                                    "tableName": "peijian" 
                                }
                            ],
                            "menu": "配件管理", // 左侧一级菜单显示的文字
                            "fontClass": "el-icon-s-tools" // ElementUI 的图标类名
                        });
                    }
                }
            });
        }

        return menuList;
    }
}

export default menu;
